  /* t484u/t485u (Dominic): off the volcano and the anvil mountain - the stretch past the Volcanic Forge (old points 45..165) is re-planned west of the cone, the
     platform / outcrop, the ape stride strip and the talk ledge (>= 250 units clear of each), through the levelled volcano-ridge choke and across the blackened ground (allowed) */
  const GK = 10, GM = newMS(); let GL = null; MS.giant = GM;
  function gLoop() { if (GL) return GL; const P = GLOOP, n = P.length, cum = [0]; for (let i = 0; i < n; i++) { const a = P[i], b = P[(i + 1) % n]; cum.push(cum[i] + Math.hypot(b[0] - a[0], b[1] - a[1])); } return (GL = { P, n, cum, L: cum[n] }); }
  /* (Dominic) trees must not poke through his legs or shell: the cheap fix is a static one - no tree is grown in his trail (feet + shell width, ~300 units
     either side of the loop (a ~95 m strip round the map), plus the tree's own crown). Map gen and the birch pass ask trailHit, so nothing pops in or out as he passes. A coarse grid keeps it fast. */
  let TH = null; function trailHit(x, y, r) { const C = 400, W0 = 300; if (!TH) { TH = new Map(); const P = GLOOP; for (let i = 0; i < P.length; i++) { const a = P[i], b = P[(i + 1) % P.length]; for (let gx = Math.floor((Math.min(a[0], b[0]) - W0 - 60) / C); gx <= Math.floor((Math.max(a[0], b[0]) + W0 + 60) / C); gx++) for (let gy = Math.floor((Math.min(a[1], b[1]) - W0 - 60) / C); gy <= Math.floor((Math.max(a[1], b[1]) + W0 + 60) / C); gy++) { const k = gx * 7919 + gy; (TH.get(k) || TH.set(k, []).get(k)).push([a[0], a[1], b[0], b[1]]); } } }
    const L = TH.get(Math.floor(x / C) * 7919 + Math.floor(y / C)); if (!L) return false; const lim = W0 + (r || 20); for (const [ax, ay, bx, by] of L) { const dx = bx - ax, dy = by - ay, l2 = dx * dx + dy * dy || 1, t = Math.max(0, Math.min(1, ((x - ax) * dx + (y - ay) * dy) / l2)); if (Math.hypot(x - ax - dx * t, y - ay - dy * t) < lim) return true; } return false; }
